// Arduino Uno R3: Verified 10-bit ADC (A0) -> 8-bit PWM (~D9)
const int POT_PIN = A0;
const int LED_PWM = 9; // Hardware PWM (~) on Uno R3

void setup() {
  pinMode(LED_PWM, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int raw = analogRead(POT_PIN);         // 0..1023 (10-bit)
  int duty = map(raw, 0, 1023, 0, 255);  // 8-bit PWM
  analogWrite(LED_PWM, duty);
  Serial.print("ADC:"); Serial.print(raw);
  Serial.print(" PWM:"); Serial.println(duty);
  delay(100);
}

// Arduino Uno R4 Minima: 12-bit ADC & True 12-bit DAC on A0
const int SENSOR_PIN = A1;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);   // 0..4095 on RA4M1
  analogWriteResolution(12);  // True 12-bit DAC on A0
}

void loop() {
  int reading = analogRead(SENSOR_PIN);
  analogWrite(A0, reading);   // Mirrors input voltage as true analog output
  Serial.println(reading);
  delay(150);
}

// Arduino Uno R4 WiFi: 12-bit ADC + Qwiic Wire1 reminder
#include <Wire.h>
const int SENSOR_PIN = A1;

void setup() {
  Serial.begin(115200);
  Wire1.begin(); // Dedicated 3.3V Qwiic I2C bus on Uno R4 WiFi
  analogReadResolution(12);
  Serial.println("Uno R4 WiFi Ready");
}

void loop() {
  Serial.println(analogRead(SENSOR_PIN));
  delay(250);
}

// Classic Arduino Nano: Reading analog-only pin A6 safely
const int LDR_PIN = A6;    // Analog-input-only on Nano Classic
const int LED_PIN = 13;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int lightVal = analogRead(LDR_PIN);
  digitalWrite(LED_PIN, lightVal < 400 ? HIGH : LOW);
  Serial.println(lightVal);
  delay(200);
}

// Arduino Nano Every: Independent Serial1 alongside USB Serial
void setup() {
  Serial.begin(9600);   // USB Monitor
  Serial1.begin(9600);  // Hardware UART on D0/D1
  Serial.println("Nano Every Dual-Serial Ready");
}

void loop() {
  if (Serial1.available()) {
    Serial.write(Serial1.read());
  }
}

// Arduino Nano 33 IoT: 3.3V 12-bit ADC safe scaling
const int SENSOR_PIN = A1;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12); // 0..4095 (0..3.3V max!)
}

void loop() {
  int raw = analogRead(SENSOR_PIN);
  float volts = (raw * 3.3f) / 4095.0f;
  Serial.println(volts, 3);
  delay(250);
}

// Arduino Nano 33 BLE Rev2: Onboard RGB LED (Active-LOW on nRF52840)
void setup() {
  pinMode(LEDR, OUTPUT);
  pinMode(LEDG, OUTPUT);
  pinMode(LEDB, OUTPUT);
  digitalWrite(LEDR, HIGH); // Active-LOW: HIGH = OFF
  digitalWrite(LEDG, HIGH);
  digitalWrite(LEDB, HIGH);
}

void loop() {
  digitalWrite(LEDB, LOW);  delay(400); // Blue ON
  digitalWrite(LEDB, HIGH); delay(400); // Blue OFF
}

