// Arduino Mega 2560: Hardware Serial1 alongside USB Serial + PWM on D44
const int MOTOR_PWM = 44; // Mega-exclusive PWM pin

void setup() {
  pinMode(MOTOR_PWM, OUTPUT);
  Serial.begin(9600);   // USB Monitor
  Serial1.begin(9600);  // Hardware UART on D18 (TX1) / D19 (RX1)
  Serial.println("Mega 2560 Multi-UART Ready");
}

void loop() {
  analogWrite(MOTOR_PWM, 160);
  if (Serial1.available()) {
    Serial.write(Serial1.read());
  }
}

// ESP32-WROOM-32 DevKit: Safe ADC1 read (GPIO 34) + LED on GPIO 2
const int SENSOR_PIN = 34; // ADC1 input-only (works even with Wi-Fi enabled)
const int LED_PIN = 2;     // Built-in LED on many ESP32 DevKits

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int raw = analogRead(SENSOR_PIN); // 12-bit: 0..4095 (0..3.3V max!)
  digitalWrite(LED_PIN, raw > 2048 ? HIGH : LOW);
  Serial.println(raw);
  delay(200);
}

